export type DictionaryCategory =
  | 'Philosophy'
  | 'Yoga'
  | 'Deity'
  | 'Scripture'
  | 'Soul & Liberation'
  | 'Cosmology'
  | 'Practice';

export interface DictionaryTerm {
  id: number;
  tamil: string;
  transliteration: string;
  english: string;
  explanation: string;
  category: DictionaryCategory;
  // verse IDs (id = verseNumber + 1) that directly illustrate this term
  verseRefs?: number[];
}

export const CATEGORY_COLORS: Record<DictionaryCategory, string> = {
  'Philosophy':       '#C8860A',
  'Yoga':             '#7B4EA0',
  'Deity':            '#C0392B',
  'Scripture':        '#1A6B8A',
  'Soul & Liberation':'#2E7D32',
  'Cosmology':        '#BF360C',
  'Practice':         '#006064',
};

// Sorted A–Z by transliteration
export const DICTIONARY_TERMS: DictionaryTerm[] = [
  { id: 1,   tamil: "அகம்",              transliteration: "agam",           english: "Inner / Within",                    explanation: "The interior space of the heart and consciousness. In the Thirumanthiram, Shiva is repeatedly said to dwell 'within' (agam), making the inner world the primary locus of spiritual discovery rather than any external place or ritual.", category: "Philosophy", verseRefs: [276, 82] },
  { id: 2,   tamil: "ஆகமம்",            transliteration: "āgamam",          english: "Agama Scripture",                   explanation: "The authoritative scriptural corpus of Shaivism, revealed by Shiva and transmitted through the guru lineage. The Agamas specify temple worship, yoga, philosophy, and ritual in precise detail. Thirumoolar's Thirumanthiram is one of the few Tamil works that directly transmits Agamic knowledge.", category: "Scripture", verseRefs: [2, 885] },
  { id: 3,   tamil: "அகந்தை",           transliteration: "aganthai",         english: "Ego / I-sense",                     explanation: "The false identification of the self with body and mind rather than with pure consciousness. The ego (ahamkāra in Sanskrit) is the root cause of bondage. Yoga and grace together dissolve this illusory sense of a separate self.", category: "Philosophy" },
  { id: 4,   tamil: "ஆகாயம்",           transliteration: "ākāyam",           english: "Ether / Space",                     explanation: "The first and subtlest of the five elements (pañca bhūta). Ākāśa corresponds to the throat centre and to the principle of sound. In the Thirumanthiram, the boundless inner space of pure consciousness is repeatedly compared to the open sky.", category: "Cosmology" },
  { id: 5,   tamil: "ஆண்டவன்",          transliteration: "āṇḍavaṉ",          english: "Lord / Ruler",                      explanation: "A common name for Shiva meaning 'the Lord who rules.' Āṇḍavan governs all of creation from within — not as an external tyrant but as the very intelligence that organises every atom and every soul.", category: "Deity" },
  { id: 6,   tamil: "ஆணவம்",            transliteration: "āṇavam",           english: "Primordial Egoism",                 explanation: "The first and most fundamental of the three bonds (pāśa) that bind the soul. Āṇava is the original contraction of consciousness — the feeling of being small and separate — from which all suffering and karma arise. Only Shiva's grace can fully dissolve it.", category: "Soul & Liberation" },
  { id: 7,   tamil: "அண்டம்",           transliteration: "aṇḍam",            english: "Cosmos / Universe",                 explanation: "The macrocosm — the external universe in all its vastness. Thirumoolar establishes that what exists in the cosmos (aṇḍam) also exists in the human body (piṇḍam), making the body a complete map of the cosmos and yoga a direct science of cosmic knowledge.", category: "Cosmology" },
  { id: 8,   tamil: "அன்பு",            transliteration: "anbu",             english: "Love / Devotion",                   explanation: "The most fundamental quality of the liberated soul and the very nature of Shiva. In Thirumoolar's radical formulation — Anbe Sivam — love is not merely a path toward Shiva but is Shiva Himself. All practices in the Thirumanthiram ultimately serve to uncover this love.", category: "Philosophy", verseRefs: [276, 82] },
  { id: 9,   tamil: "அன்பே சிவம்",      transliteration: "anbe sivam",        english: "Love is Shiva",                     explanation: "The single most celebrated declaration in the entire Thirumanthiram (verse 81). This four-word phrase is both a complete philosophy and a direct experiential pointer: the experience of unconditional love and the experience of Shiva are not two different things.", category: "Philosophy", verseRefs: [82, 276] },
  { id: 10,  tamil: "அருள்",            transliteration: "aruḷ",             english: "Grace / Divine Grace",              explanation: "Shiva's unconditional compassion that actively works to bring all souls toward liberation. Unlike karma which is earned through action, aruḷ is freely given. The entire Thirumanthiram can be read as a detailed account of how divine grace operates and how the soul can open itself to receive it.", category: "Deity", verseRefs: [2, 3] },
  { id: 11,  tamil: "அருட்பெரும் சோதி", transliteration: "aruṭperum jōthi",  english: "Great Light of Grace",              explanation: "One of the most exalted names of Shiva in Tamil tradition — 'the vast, radiant light of divine grace.' This is also the title of the great mystical poem by the 19th-century saint Vallalar, who identified this inner light as the supreme form of the divine.", category: "Deity", verseRefs: [2] },
  { id: 12,  tamil: "ஆத்மா",            transliteration: "āttmā",            english: "Soul / Self",                       explanation: "The individual soul — one of the three eternal realities in Shaiva Siddhanta. The soul exists eternally but is currently bound by the three pāśas. Through grace and yoga, it is progressively liberated until it exists in eternal conscious union with Shiva.", category: "Soul & Liberation", verseRefs: [2123, 2650] },
  { id: 13,  tamil: "ஆவி",              transliteration: "āvi",              english: "Breath / Spirit / Life-force",       explanation: "Refers to both the physical breath and the prāṇa (life-force) that animates the body. In the Thirumanthiram, the breath is the most direct connection between the individual and the cosmos — controlling the breath is the master key to controlling the mind.", category: "Yoga", verseRefs: [550] },
  { id: 14,  tamil: "அஷ்டாங்க யோகம்",  transliteration: "aṣṭāṅga yōgam",    english: "Eightfold Yoga",                    explanation: "The classical eight-limbed yoga system: Yama, Niyama, Āsana, Prāṇāyāma, Pratyāhāra, Dhāraṇā, Dhyāna, and Samādhi. The entirety of Tantra 3 of the Thirumanthiram expounds this system in comprehensive detail, making it one of the oldest Tamil yogic manuals.", category: "Yoga", verseRefs: [550, 551] },

  { id: 15,  tamil: "பஞ்சாக்கரம்",     transliteration: "bañcākṣaram",      english: "Five-lettered Mantra",              explanation: "The sacred mantra Na-Ma-Si-Va-Ya (நம சி வா ய). Each syllable corresponds to one of the five elements, one of the five cosmic acts of Shiva, and one of the five divine functions. Tantra 4 of the Thirumanthiram is dedicated to its profound exposition.", category: "Practice", verseRefs: [885, 886] },
  { id: 16,  tamil: "பந்தம்",           transliteration: "bantham",          english: "Bond / Bondage",                    explanation: "The condition of the soul bound to the cycle of birth and death. Shaiva Siddhanta identifies three bonds: āṇava (primordial ego), karma, and māyā. Liberation is the complete dissolution of all three bonds through Shiva's grace, not through the soul's own unaided effort.", category: "Soul & Liberation", verseRefs: [2123, 2650] },

  { id: 17,  tamil: "சக்தி",            transliteration: "cakti",            english: "Divine Energy / Power of Shiva",    explanation: "The dynamic, creative energy of Shiva — both the power of Shiva and the Goddess Herself as a distinct reality. Shakti is not separate from Shiva but is His own power of expression. Tantra 4 of the Thirumanthiram dedicates many verses to the glory of Shakti in all her forms.", category: "Deity", verseRefs: [885, 2] },
  { id: 18,  tamil: "சகலம்",            transliteration: "cagalam",          english: "All Things / Total Manifest Reality", explanation: "The totality of manifest existence. In Shaiva Siddhanta, sakala describes the level of reality where souls experience the world through the instruments of body and mind. The soul at this level is fully bound and fully engaged with the world.", category: "Cosmology" },
  { id: 19,  tamil: "சமாதி",            transliteration: "camādhi",          english: "Complete Absorption / Union",        explanation: "The eighth limb of Ashtanga yoga — the state of complete absorption of the individual mind into pure consciousness. In Shaiva yoga, samādhi is not an achievement but a revelation: the direct recognition that the individual and Shiva were never actually separate.", category: "Yoga", verseRefs: [550, 2123] },
  { id: 20,  tamil: "சம்சாரம்",         transliteration: "camsāram",         english: "Cycle of Rebirth",                  explanation: "The beginningless cycle of birth, death, and rebirth driven by karma and the three bonds. The Thirumanthiram does not view the world negatively — samsāra is the soul's school, the arena in which it gradually matures through experience toward liberation.", category: "Philosophy" },
  { id: 21,  tamil: "சரண்",             transliteration: "caraṇ",            english: "Refuge / Surrender",                explanation: "Taking refuge at the feet of Shiva or the guru. Surrender is not passive submission but an active reorientation of the will — instead of the ego directing life, the soul consciously aligns itself with Shiva's intelligence. This is the beginning of liberation.", category: "Practice", verseRefs: [2, 35] },
  { id: 22,  tamil: "சித்தம்",          transliteration: "cittam",           english: "Mind-stuff / Consciousness-field",   explanation: "The total mental apparatus — memory, ego, intellect, and raw awareness combined. In yoga, purifying the citta is the central project: removing the obscurations that prevent the citta from reflecting pure consciousness clearly, like polishing a mirror.", category: "Philosophy", verseRefs: [550] },
  { id: 23,  tamil: "சித்தர்",          transliteration: "cittar",           english: "Siddhar / Perfected One",            explanation: "A perfected yogi who has attained both liberation and supernatural powers through intensive practice. The Tamil Siddhar tradition, of which Thirumoolar is the most prominent voice, emphasises the complete transformation of body and mind into vehicles of divine consciousness.", category: "Soul & Liberation", verseRefs: [80, 1705] },
  { id: 24,  tamil: "சித்தி",           transliteration: "citti",            english: "Supernatural Power / Attainment",    explanation: "The eight great supernatural powers attained by advanced yogis: miniaturisation, magnification, levitation, extension, omnipresence, mastery, lordship, and creative power. Tantra 7 of the Thirumanthiram expounds these in detail, while warning that siddhis are not the goal but by-products of genuine liberation.", category: "Yoga", verseRefs: [1705, 1706] },
  { id: 25,  tamil: "சிவம்",            transliteration: "civam",            english: "Shiva / Absolute Goodness",          explanation: "The supreme reality of Shaivism — both the personal God and the impersonal absolute. The word means 'the auspicious one' or 'absolute goodness.' Thirumoolar uses Sivam to mean both the transcendent absolute and the loving, intimate divine presence accessible in the heart.", category: "Deity", verseRefs: [2, 82, 276] },
  { id: 26,  tamil: "சிவஞானம்",         transliteration: "civañānam",        english: "Knowledge of Shiva / Shiva-gnosis",  explanation: "The direct experiential knowledge of Shiva as one's own true nature — not intellectual theology but the living recognition that the self and Shiva are not two. Tantra 8 of the Thirumanthiram is entirely devoted to the nature and attainment of Shiva-jñāna.", category: "Philosophy", verseRefs: [2123, 2124] },
  { id: 27,  tamil: "சிவயோகம்",         transliteration: "civayōgam",        english: "Shiva Yoga",                        explanation: "The advanced yoga of direct union with Shiva, transcending the outer limbs of Ashtanga yoga. In Shiva Yoga, the distinction between practitioner and Shiva progressively dissolves until only Shiva remains.", category: "Yoga", verseRefs: [1574, 550] },
  { id: 28,  tamil: "சோதி",             transliteration: "cōti",             english: "Light / Divine Flame",               explanation: "A key image in the Thirumanthiram for Shiva's nature — pure luminous awareness that illumines everything without itself being illumined by anything external. Thirumoolar frequently describes the inner experience of Shiva as a blazing, self-luminous light at the crown of the head.", category: "Deity", verseRefs: [2, 2123] },
  { id: 29,  tamil: "சுழுமுனை",         transliteration: "cuḻumuṉai",        english: "Sushumna / Central Channel",         explanation: "The central energy channel (nāḍī) running along the spine through which the Kundalini energy rises during advanced yoga. In the Thirumanthiram, awakening the sushumna by balancing the solar and lunar channels is the core technical teaching of the yogic path.", category: "Yoga", verseRefs: [550, 885] },

  { id: 30,  tamil: "தவம்",             transliteration: "tavam",            english: "Austerity / Tapas",                  explanation: "Disciplined spiritual practice, especially sustained meditation. In the Thirumanthiram, tavam is not self-torture but the focused, sustained turning of attention toward Shiva — the inner 'heat' of concentration that burns away impurities and reveals the divine clarity beneath.", category: "Practice", verseRefs: [1574, 1575] },
  { id: 31,  tamil: "தத்துவம்",         transliteration: "tattuam",          english: "Principle / Category of Reality",    explanation: "The fundamental principles or categories that constitute reality. Shaiva Siddhanta enumerates 36 tattvas from pure Shiva-consciousness at the summit to earth at the base. Knowing the tattvas is the cosmological framework of Shaiva thought.", category: "Philosophy", verseRefs: [338, 2123] },
  { id: 32,  tamil: "தந்திரம்",         transliteration: "tanttiram",        english: "Tantra / Sacred Method / Section",   explanation: "Both a title for each of the nine sections of the Thirumanthiram and a term for the broader tradition of Tantric practice. Tantra means 'that which expands' — practices that expand consciousness by working through the body and senses rather than against them.", category: "Scripture", verseRefs: [2, 338] },
  { id: 33,  tamil: "தீட்சை",           transliteration: "thīṭcai",          english: "Initiation / Dīkṣā",                explanation: "The formal transmission of spiritual power from guru to disciple that begins the disciple's journey in earnest. In Shaiva tradition, dīkṣā is not merely a ceremony but an actual transmission of grace that begins the real dissolution of the soul's three bonds.", category: "Practice", verseRefs: [1574] },
  { id: 34,  tamil: "திரோதம்",          transliteration: "thirōtham",        english: "Concealment / Veiling Grace",        explanation: "One of Shiva's five cosmic acts — the power by which Shiva conceals Himself, creating the experience of separation and apparent ignorance. Tirodhāna serves the soul's development by giving it the experience of limitation that makes the eventual return to union meaningful.", category: "Cosmology", verseRefs: [338] },
  { id: 35,  tamil: "திருவடி",          transliteration: "thiruvadi",        english: "Sacred Feet (of Shiva / Guru)",       explanation: "The feet of Shiva or the guru — one of the most important objects of devotion in the Thirumanthiram. Taking refuge at the sacred feet represents complete surrender, humility, and the abandonment of ego's independence. The feet also symbolise grace descending from the divine to the human.", category: "Practice", verseRefs: [2, 80] },
  { id: 36,  tamil: "திருவருள்",        transliteration: "thiruvaruḷ",       english: "Sacred Divine Grace",               explanation: "The most exalted expression for Shiva's grace in Tamil tradition — combining thiru (sacred, auspicious) with aruḷ (grace). Thiruvaruḷ is not passive kindness but the active, intelligent divine power that specifically works to dissolve the soul's bonds and bring it to liberation.", category: "Deity", verseRefs: [2, 3] },
  { id: 37,  tamil: "திருமூலர்",        transliteration: "thirumūlar",       english: "Thirumoolar / Sacred Mulan",         explanation: "The author of the Thirumanthiram — a Siddhar yogi from Kailash who came to Tamil Nadu, inhabited the body of a cowherd named Mulan, and over thousands of years composed 3,047 verses of direct spiritual transmission from samādhi.", category: "Deity", verseRefs: [80, 82, 69] },
  { id: 38,  tamil: "தொண்டு",           transliteration: "thoṇḍu",           english: "Service / Devoted Service",          explanation: "Selfless service rendered to Shiva and to all beings as a natural expression of love. In Shaiva devotion, thoṇḍu is not servile duty but love made active — the overflow of devotion expressed as care, dedication, and tireless service to others.", category: "Practice" },
  { id: 39,  tamil: "துரீயம்",          transliteration: "thurīyam",         english: "The Fourth State / Turiya",          explanation: "The fourth state of consciousness, beyond waking, dreaming, and deep sleep. Turiya is pure witnessing awareness — the presence that observes all three ordinary states without being changed by any of them. It is the direct experience of Shiva as the ground of all consciousness.", category: "Philosophy", verseRefs: [2123, 550] },
  { id: 40,  tamil: "துரியாதீதம்",      transliteration: "thuriyāthīdam",    english: "Beyond the Fourth / Turiyātīta",    explanation: "The state beyond turiya — not a fifth state but the recognition that the witnessing awareness of turiya pervades and is the ground of all states. In turiyātīta, Shiva-consciousness is continuous and unbroken through all activities and all states of experience.", category: "Philosophy", verseRefs: [2123] },

  { id: 41,  tamil: "ஈசன்",             transliteration: "īcan",             english: "The Ruler / Lord Shiva",             explanation: "A common name for Shiva meaning 'the Lord' or 'the Ruler.' In the Thirumanthiram, Īśan is both the cosmic sovereign who governs all reality through His five acts, and the intimate, accessible presence dwelling in the heart of every being without distinction.", category: "Deity", verseRefs: [2, 338] },
  { id: 42,  tamil: "இச்சை",            transliteration: "icai",             english: "Will / Desire-power",               explanation: "The power of divine will — one of the five shaktis of Shiva. In the purified soul, icchā-śakti becomes aligned with Shiva's will, at which point there is no longer any meaningful distinction between personal desire and the purpose of the divine. Yoga purifies this faculty.", category: "Philosophy" },
  { id: 43,  tamil: "இடகலை",            transliteration: "iḍakalai",         english: "Ida / Left Lunar Channel",           explanation: "The left energy channel (nāḍī) in yogic physiology, associated with the moon, cooling energy, the feminine principle, and the in-breath. When the solar (piṅgalā) and lunar (iḍā) channels are balanced, the central channel (suṣumnā) opens spontaneously.", category: "Yoga", verseRefs: [550, 885] },

  { id: 44,  tamil: "காம்",             transliteration: "kām",              english: "Desire / Divine Longing",            explanation: "Desire in its many forms — from gross sensory craving to the soul's deep longing for Shiva. In the Thirumanthiram, desire is not simply condemned. The longing for union with Shiva is itself a form of divine desire (divya kāma) that, when recognised as such, becomes the most powerful fuel for liberation.", category: "Philosophy" },
  { id: 45,  tamil: "கமலம்",            transliteration: "kamalam",          english: "Lotus",                             explanation: "A recurring symbol for spiritual unfoldment and purity. The lotus grows from mud yet remains unstained — a perfect image for the soul dwelling in the world without being corrupted by it. The heart-lotus (hṛdaya kamala) is the inner dwelling place of Shiva within the body.", category: "Philosophy" },
  { id: 46,  tamil: "கண்ணி மணி",       transliteration: "kaṇṇin maṇi",      english: "Jewel of the Eye",                  explanation: "A poetic image in the Thirumanthiram for the subtle centre of inner vision — the spiritual faculty of direct perception through which Shiva is perceived. When attention rests at this inner centre, the divine light becomes visible to the purified awareness.", category: "Practice" },
  { id: 47,  tamil: "கர்மம்",           transliteration: "karmam",           english: "Karma / Action-residue",             explanation: "The accumulated residue of past actions that shapes present experience and binds the soul to rebirth. Karma is the second of the three bonds (pāśa). It is not punishment but a natural law — actions create tendencies that continue until dissolved by grace and awareness.", category: "Soul & Liberation", verseRefs: [2, 114] },
  { id: 48,  tamil: "கைவல்யம்",         transliteration: "kaivalyam",        english: "Absolute Liberation",               explanation: "The complete and final liberation of the soul — standing alone in pure awareness, free from all bonds. In Shaiva Siddhanta, kaivalya is not isolation but the recognition of eternal freedom in Shiva, where the soul retains its individual identity while fully dwelling in Shiva's nature.", category: "Soul & Liberation", verseRefs: [2650, 2651] },
  { id: 49,  tamil: "கிரியை",           transliteration: "kiriyai",          english: "Action / Ritual Action (Kriyā)",     explanation: "The path of ritual action and worship as a means of spiritual progress. Kriyā is one of the four approaches (pādas) of the Shaiva Agamas, along with Caryā (ethics), Yoga (inner practice), and Jñāna (knowledge). All four are necessary for complete realisation.", category: "Practice" },
  { id: 50,  tamil: "குண்டலினி",        transliteration: "kuṇḍalinī",        english: "Coiled Energy / Serpent Power",      explanation: "The dormant spiritual energy coiled at the base of the spine, which when awakened rises through the central channel, activating the chakras and ultimately merging with Shiva at the crown. The Thirumanthiram is one of the earliest Tamil texts to describe this process in systematic detail.", category: "Yoga", verseRefs: [550, 885, 1705] },
  { id: 51,  tamil: "குரு",             transliteration: "guru",             english: "Spiritual Teacher",                  explanation: "The spiritual master who transmits knowledge and grace to the disciple. In Shaiva tradition, the guru is not merely a human teacher but a manifestation of Shiva's grace — Shiva Himself appearing in human form to guide the soul. Nandi is considered the primordial guru of all.", category: "Practice", verseRefs: [1574, 69, 2] },

  { id: 52,  tamil: "லட்சணம்",          transliteration: "laṭcaṇam",         english: "Sign / Characteristic / Lakshana",  explanation: "The signs or characteristics by which a realised master can be recognised — absence of fear, absence of pride, constant equanimity, all-pervading compassion. Thirumoolar lists several lakshanas of the liberated one to guide disciples in recognising genuine spiritual attainment.", category: "Soul & Liberation" },
  { id: 53,  tamil: "லிங்கம்",          transliteration: "liṅgam",           english: "Shiva's Form / Axis of Consciousness", explanation: "The primary iconic form of Shiva worship — an upright column representing the infinite, self-luminous axis of consciousness. In Thirumoolar's teaching, the liṅgam is both an external object of worship and an inner reality — the pillar of pure awareness at the centre of the body.", category: "Deity", verseRefs: [1705, 885] },

  { id: 54,  tamil: "மந்திரம்",         transliteration: "manthiram",        english: "Sacred Formula / Mantra",            explanation: "A sacred syllable or phrase whose sustained repetition purifies the mind and reveals the divine. The Thirumanthiram itself — Thiru-manthiram — means 'the sacred mantra,' implying the entire text is itself a mantra that liberates those who receive it with devotion.", category: "Practice", verseRefs: [885, 886] },
  { id: 55,  tamil: "மனம்",             transliteration: "manam",            english: "Mind",                              explanation: "The instrument of knowing, feeling, and willing that mediates between consciousness and the world. The Thirumanthiram identifies the mind as the single most important factor in bondage and liberation — the same mind that creates suffering, when purified, becomes the very dwelling place of Shiva.", category: "Philosophy", verseRefs: [550, 276] },
  { id: 56,  tamil: "மாயை",             transliteration: "māyai",            english: "Illusion / Matter-energy",           explanation: "The third of the three bonds (pāśa) — the cosmic principle of material existence and apparent multiplicity that causes the soul to identify with the body rather than with consciousness. In Shaiva Siddhanta, māyā is real but subservient to Shiva's will.", category: "Soul & Liberation", verseRefs: [2123, 338] },
  { id: 57,  tamil: "முக்தி",           transliteration: "mukti",            english: "Liberation / Freedom",              explanation: "The complete freedom of the soul from all bonds — the goal of all spiritual life. In Shaiva Siddhanta, mukti is not annihilation of the individual but its fulfillment: the soul, freed from the three bonds, exists in eternal loving conscious union with Shiva.", category: "Soul & Liberation", verseRefs: [2650, 2651, 2123] },
  { id: 58,  tamil: "மூலம்",            transliteration: "mūlam",            english: "Root / Origin",                     explanation: "The root or ultimate source. In yogic physiology, the mūlādhāra chakra at the base of the spine is the seat of dormant Kundalini energy. In philosophy, Shiva as mūlam is the uncaused cause — the root from which all existence springs without any prior cause.", category: "Yoga", verseRefs: [550, 2] },
  { id: 59,  tamil: "மூலன்",            transliteration: "mūlaṉ",            english: "The Root One / Mulan (Thirumoolar's form)", explanation: "The original name of the cowherd whose body Thirumoolar inhabited through the yogic power of parakāya pravēsa. When Thirumoolar's original body vanished, he continued in Mulan's form, and 'Thirumoolar' — the sacred Mulan — became his name for all time.", category: "Deity", verseRefs: [80, 82] },
  { id: 60,  tamil: "முத்தி",           transliteration: "mutti",            english: "Liberation (Tantra 9 title)",         explanation: "An alternate Tamil form of mukti — the complete liberation from the cycle of rebirth. Tantra 9 of the Thirumanthiram bears this title and describes in detail the nature of the liberated state, the liberated soul's relationship with Shiva, and the eternal bliss of liberation.", category: "Soul & Liberation", verseRefs: [2650, 2651] },

  { id: 61,  tamil: "நந்தி",            transliteration: "nanti",            english: "Nandi / Divine Bull / Primordial Guru", explanation: "Shiva's sacred vehicle and the first teacher of the Shaiva yoga lineage. Thirumoolar received initiation directly from Nandi at Kailash, making Nandi his root guru. Nandi represents the pure, faithful soul that carries the divine and dwells always in Shiva's presence.", category: "Deity", verseRefs: [2, 3, 69] },
  { id: 62,  tamil: "நமசிவாய",          transliteration: "namasivāya",       english: "Na-Ma-Si-Va-Ya (Panchakshara)",      explanation: "The five-syllable sacred mantra of Shaivism. Na = earth/Brahma, Ma = water/Vishnu, Si = fire/Rudra, Va = air/Maheshvara, Ya = space/Sadāshiva. These five syllables contain the entire cosmology of Shaivism and the complete path of liberation within them.", category: "Practice", verseRefs: [885, 886, 887] },
  { id: 63,  tamil: "நாதம்",            transliteration: "nātam",            english: "Primordial Sound / Inner Sound",      explanation: "The inner sound of consciousness — the unstruck, self-arising sound (anāhata nāda) that can be heard in deep meditation as the hum of pure awareness. In the Thirumanthiram, nāda is the subtlest form of Shiva's creative expression, prior to all manifest sound.", category: "Cosmology", verseRefs: [885, 338] },
  { id: 64,  tamil: "நிலை",             transliteration: "nilai",            english: "State / Ground / Stability",         explanation: "The stable ground of being — the unwavering state of the liberated yogi who is no longer moved by the fluctuations of mind and circumstance. 'Established in silence' (mōṉē nilaiperṟār) is Thirumoolar's description of the ones who have found this unshakeable ground in Shiva.", category: "Soul & Liberation", verseRefs: [2650, 2123] },

  { id: 65,  tamil: "ஓம்",              transliteration: "ōm",               english: "Om / Pranava",                      explanation: "The primordial sacred syllable composed of A, U, and M, representing the three states of consciousness and transcending them into the fourth (turiya). Om is the sound-form of Shiva and the seed of all mantras. Meditation on Om is described as equivalent to meditating on Shiva directly.", category: "Practice", verseRefs: [885, 2] },
  { id: 66,  tamil: "ஒளி",              transliteration: "oḷi",              english: "Light / Luminosity",                explanation: "A primary metaphor in the Thirumanthiram for Shiva's nature and for the inner experience of the divine. Thirumoolar uses light imagery constantly — inner light, light of grace, light at the crown — pointing to the self-luminous nature of pure consciousness that illumines everything without itself needing illumination.", category: "Deity", verseRefs: [2, 2123] },

  { id: 67,  tamil: "பாடல்",            transliteration: "pāḍal",            english: "Song / Verse",                      explanation: "Each of the 3,047 verses of the Thirumanthiram. Unlike literary compositions, Thirumoolar's pāḍal are described as direct transmissions from deep samādhi — each verse a report of lived spiritual experience, composed once each year after emerging from prolonged absorption.", category: "Scripture", verseRefs: [82, 2] },
  { id: 68,  tamil: "பரகாயப் பிரவேசம்", transliteration: "parakāya pravēsam", english: "Entry into Another Body",           explanation: "The yogic power by which a yogi can vacate their own body and inhabit another. This is the central miracle in Thirumoolar's biography — he entered the body of the dead cowherd Mulan. This led directly to his remaining in Tamil Nadu and composing the Thirumanthiram.", category: "Yoga", verseRefs: [80] },
  { id: 69,  tamil: "பரமன்",            transliteration: "paraman",          english: "The Supreme Being",                  explanation: "A common name for Shiva in the Thirumanthiram, emphasising His supremacy over all gods and all levels of reality. Paraman is beyond all creation, yet is the very source and sustainer of creation — both utterly transcendent and intimately immanent.", category: "Deity", verseRefs: [2, 3] },
  { id: 70,  tamil: "பரம்",             transliteration: "param",            english: "The Supreme / Transcendent",         explanation: "The highest or transcendent aspect of Shiva — beyond all qualities, forms, and concepts. Shiva is both param (transcendent) and aparam (immanent). To realise Shiva as param is the pinnacle of the highest knowledge (parā jñāna) described in the Thirumanthiram.", category: "Deity", verseRefs: [2, 2123] },
  { id: 71,  tamil: "பசு",              transliteration: "pacu",             english: "Soul / Bound Being",                 explanation: "Literally 'cow,' used in Shaiva Siddhanta as a technical term for the individual soul in its bound state. The term emphasises the soul's current dependence and ignorance — like a domestic animal tethered to a post — without implying this is its permanent or essential nature.", category: "Soul & Liberation", verseRefs: [2123, 114] },
  { id: 72,  tamil: "பாசம்",            transliteration: "pācam",            english: "Bond / Fetter / Noose",              explanation: "Literally 'rope' or 'noose,' the technical Shaiva term for the three bonds that bind the soul: āṇava, karma, and māyā. The pāśa is real but not eternal — it can be dissolved by Shiva's grace. All of spiritual life is, in essence, the process of untying these three knots.", category: "Soul & Liberation", verseRefs: [2123, 338] },
  { id: 73,  tamil: "பதி",              transliteration: "pathi",            english: "Lord / God (Shiva) — First Eternal", explanation: "The first of the three eternal realities in Shaiva Siddhanta: Pati (God), Paśu (soul), Pāśa (bond). Pati means 'Lord' or 'master' — the supreme reality that is eternally free, omniscient, and omnipotent. Shiva as Pati is the ultimate refuge and the final truth.", category: "Deity", verseRefs: [2, 2123] },
  { id: 74,  tamil: "பிண்டம்",          transliteration: "piṇḍam",           english: "Body / Microcosm",                   explanation: "The individual human body, understood as a microcosm of the entire universe (aṇḍam). What exists in the cosmos exists in the body — this equivalence is the foundation of the entire yogic science of the Thirumanthiram and justifies the body as the primary field of spiritual investigation.", category: "Cosmology", verseRefs: [2, 550] },
  { id: 75,  tamil: "பிரணவம்",          transliteration: "praṇavam",         english: "Pranava / Sacred Om",               explanation: "The primordial sound Om in its subtlest, unmanifest form — prior to vibration, prior to all sound. Meditation on the pranava is considered equivalent to meditating on Shiva Himself. In the body, the pranava resounds as the subtle inner hum of consciousness.", category: "Practice", verseRefs: [885, 886] },
  { id: 76,  tamil: "பிராணன்",          transliteration: "prāṇan",           english: "Life-force / Prana",                explanation: "The vital energy that animates the body and connects individual consciousness to the cosmic. Through prāṇāyāma (breath control), the yogi can influence the flow of prāṇa through all channels, purifying the subtle body and quieting the mind for deep meditation.", category: "Yoga", verseRefs: [550, 551] },
  { id: 77,  tamil: "புலன்கள்",         transliteration: "pulankaḷ",         english: "Senses / Sense Faculties",           explanation: "The five senses — sight, sound, smell, taste, touch — and their corresponding organs. In yoga, the senses are instruments of knowledge that must be trained to turn inward (pratyāhāra). When properly directed, they become transparent windows to the divine rather than conduits of distraction.", category: "Yoga", verseRefs: [550] },
  { id: 78,  tamil: "புண்ணியம்",        transliteration: "puṇṇiyam",         english: "Merit / Virtuous Action",            explanation: "Positive karma accumulated through good actions, devotion, and ethical living. Puṇya creates favourable conditions for spiritual practice. However, the Thirumanthiram consistently points beyond even puṇya to grace (aruḷ) as the ultimate liberating force that no amount of merit can substitute.", category: "Philosophy", verseRefs: [114] },

  { id: 79,  tamil: "ருத்திரன்",        transliteration: "ruttiram",         english: "Rudra / Shiva as Dissolver",         explanation: "A name of Shiva emphasising His dissolving, terrifying aspect. Rudra destroys what is false, impure, or obstructive — His apparent terror is the grace of destruction. In the Thirumanthiram, Rudra is one of Shiva's five roles in the cosmic dance of creation and dissolution.", category: "Deity", verseRefs: [338, 2] },

  { id: 80,  tamil: "சங்கரன்",          transliteration: "sangharan",        english: "Shankara / The Beneficent One",      explanation: "A name of Shiva meaning 'He who bestows auspiciousness.' Shankar is Shiva in His grace-giving aspect — the one who bestows liberation, wisdom, health, and all that is genuinely good upon those who approach Him with devotion and surrender.", category: "Deity", verseRefs: [2, 3] },
  { id: 81,  tamil: "சிவாகமம்",         transliteration: "civākamam",        english: "Shaiva Agama",                      explanation: "The authoritative scriptural tradition of Shaivism — texts revealed by Shiva that govern worship, yoga, philosophy, and cosmology. Tantra 4 of the Thirumanthiram is devoted to the Shaiva Agamas, establishing the scriptural authority behind the entire Thirumanthiram tradition.", category: "Scripture", verseRefs: [885, 2] },
  { id: 82,  tamil: "சிவலோகம்",         transliteration: "civalōgam",        english: "Realm of Shiva",                    explanation: "The highest spiritual realm — the abode of Shiva and of liberated souls. In Shaiva Siddhanta, Sivaloka is not merely a physical heaven but a state of consciousness: the state in which Shiva is directly known and all bonds are dissolved.", category: "Cosmology", verseRefs: [2650, 2123] },

  { id: 83,  tamil: "உடல்",             transliteration: "uḍal",             english: "Body / Physical Form",              explanation: "The physical body, which Thirumoolar famously declares to be sacred and necessary for liberation. 'If the body perishes, the life perishes' — the body is not an obstacle to be overcome but the vehicle of liberation itself, to be purified and transformed through yoga until it becomes a fit dwelling for Shiva.", category: "Yoga", verseRefs: [114, 550] },
  { id: 84,  tamil: "உணர்வு",           transliteration: "uṇarvu",           english: "Awareness / Consciousness",         explanation: "Pure awareness — the knowing quality of consciousness that pervades all experience. Thirumoolar's tripartite formula — body (ūṉ), life (uyir), consciousness (uṇarvu) — names the three dimensions of human existence that must all be brought into alignment with Shiva in the practice of yoga.", category: "Philosophy", verseRefs: [550, 2123] },
  { id: 85,  tamil: "உலகம்",            transliteration: "ulagam",           english: "World / This World",               explanation: "The manifest world of experience — not condemned as illusory or evil, but seen as Shiva's creation and the field in which souls learn, grow, and eventually recognise their divine nature. The world is not to be fled from but seen through, until Shiva is recognised as its very substance.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 86,  tamil: "உள்ளம்",           transliteration: "uḷḷam",            english: "Heart / Inner Being",               explanation: "The heart as the seat of consciousness and feeling — not the physical organ but the inner centre of awareness where Shiva resides. The heart-lotus (uḷḷa kamalam) is Shiva's dwelling place within the human body, the place to which all meditation ultimately returns.", category: "Philosophy", verseRefs: [276, 82] },
  { id: 87,  tamil: "உயிர்",            transliteration: "uyir",             english: "Life / Soul / Breath",              explanation: "The living spirit or life-force — used in the Thirumanthiram both for the physical life-breath and for the soul itself. Uyir is the animating principle that makes the body a living being; without uyir, the body (uḍal) is merely inert matter. Preserving and purifying the uyir is the work of yoga.", category: "Soul & Liberation", verseRefs: [114, 550] },

  { id: 88,  tamil: "வழி",              transliteration: "vaḻi",             english: "Path / Way",                        explanation: "The spiritual path — both the outer path of practice and the inner path of recognition. Thirumoolar describes multiple paths to Shiva and consistently points to the innermost path: the turning of attention from outer phenomena to the source of awareness itself, which is Shiva.", category: "Practice", verseRefs: [1420, 550] },
  { id: 89,  tamil: "வேதம்",            transliteration: "vētam",            english: "Veda / Sacred Knowledge",           explanation: "The ancient Sanskrit scriptures of India — the four Vedas (Rig, Yajur, Sama, Atharva). Thirumoolar integrates the Vedic and Agamic traditions, showing they are not contradictory but complementary expressions of the same truth about Shiva. He claims to have heard the Vedas from Shiva Himself.", category: "Scripture", verseRefs: [2, 3] },
  { id: 90,  tamil: "விடுதலை",          transliteration: "viḍuthalai",       english: "Liberation / Freedom / Release",    explanation: "The Tamil word for liberation — both spiritual liberation from the three bonds and the freedom of consciousness recognising its own nature as Shiva. In Thirumoolar's teaching, viḍuthalai is not a distant future goal but a present recognition available to anyone who knows how to look inward.", category: "Soul & Liberation", verseRefs: [2650, 2123] },
  { id: 91,  tamil: "வினை",             transliteration: "vinai",            english: "Karma / Action-residue",             explanation: "The accumulated residue of actions from all past lives that shapes the soul's present and future experience. Vinai is synonymous with karma — the binding force of past deeds. Through yoga, devotion, and grace, accumulated vinai is gradually dissolved until the soul is completely free.", category: "Soul & Liberation", verseRefs: [114, 2123] },
  { id: 92,  tamil: "விண்",             transliteration: "viṇ",              english: "Sky / Heaven / Infinite Space",     explanation: "The sky or celestial space — used both literally and as a symbol for the infinite expanse of pure consciousness. Thirumoolar describes the state of liberation as the mind expanding like the sky — without boundaries, without divisions, luminous and free, containing everything without being contained by anything.", category: "Cosmology", verseRefs: [2650, 2] },

  { id: 93,  tamil: "யமம்",             transliteration: "yamam",            english: "Yama / Ethical Restraints",         explanation: "The first of the eight limbs of yoga — the ethical foundations of spiritual life: non-violence, truthfulness, non-stealing, celibacy, and non-possessiveness. Thirumoolar teaches that without these foundations, no higher yoga is possible; they are the ground on which the entire practice is built.", category: "Yoga", verseRefs: [550, 551] },
  { id: 94,  tamil: "யோகம்",            transliteration: "yōgam",            english: "Yoga / Union",                      explanation: "The broad path of practices leading to union with Shiva — including ethical conduct, posture, breath, sense-withdrawal, concentration, meditation, and absorption. In the Thirumanthiram, yoga is not merely physical exercise but the complete science of consciousness, expounded in its most comprehensive form in Tantra 3.", category: "Yoga", verseRefs: [550, 551, 1420] },
  { id: 95,  tamil: "யோகி",             transliteration: "yōgi",             english: "Yogi / One Who Practices Yoga",     explanation: "A practitioner of yoga — not merely one who does physical postures but one who has dedicated their entire being to the project of union with Shiva. Thirumoolar himself is the supreme example: thousands of years in samādhi, emerging once each year to transmit a verse of direct spiritual experience.", category: "Yoga", verseRefs: [80, 550, 2123] },

  // ── Deity (additional names and forms) ──────────────────────────────────────
  { id: 96,  tamil: "உமை",                  transliteration: "umai",               english: "Uma / Parvati — Shiva's Consort",           explanation: "The divine consort of Shiva and the embodiment of Shakti in her most intimate form. Uma is simultaneously the cosmic mother, the great Goddess, and the feminine half of ultimate reality. In the Thirumanthiram, Uma is inseparable from Shiva — together they form the complete divine reality. Shiva without Uma is stillness; Uma without Shiva is blind energy.", category: "Deity", verseRefs: [550, 2] },
  { id: 97,  tamil: "கணேசன்",               transliteration: "kaṇēcaṉ",             english: "Ganesha / Remover of Obstacles",             explanation: "The elephant-headed son of Shiva and Parvati, the remover of obstacles, and the lord of beginnings. In the Thirumanthiram, Ganesha appears in the opening Vinayagar Kaapu — all spiritual undertakings are placed under his protection before proceeding. His curved trunk points inward, symbolising the turning of the mind back to its source.", category: "Deity", verseRefs: [1] },
  { id: 98,  tamil: "முருகன்",               transliteration: "murukaṉ",             english: "Murugan / Skanda — Son of Shiva",             explanation: "Son of Shiva and Parvati and the most beloved deity of Tamil Nadu. Murugan represents the highest energy of Shiva's grace — eternally youthful, eternally victorious, wielding the divine lance (Vel) that destroys ignorance. Tamil Shaivism reveres Murugan as the very embodiment of Shiva's loving, accessible nature and the patron deity of Tamil itself.", category: "Deity" },
  { id: 99,  tamil: "சதாசிவம்",              transliteration: "catācivam",           english: "Sadashiva — The Eternal Shiva",               explanation: "The highest, most transcendent form of Shiva — 'eternally auspicious.' Sadashiva is Shiva beyond all cosmic cycles, the pure absolute from which even the five aspects (Brahma, Vishnu, Rudra, Maheshvara, Sadashiva) emerge. In the Thirumanthiram, the yogi who has fully dissolved into Shiva is said to abide as Sadashiva — no longer a separate person but an eternal presence.", category: "Deity", verseRefs: [2123, 2] },
  { id: 100, tamil: "நடராஜன்",               transliteration: "naṭarājaṉ",           english: "Nataraja — Lord of the Cosmic Dance",         explanation: "Shiva in the form of the cosmic dancer — the most philosophically rich image in all of Shaiva tradition. Nataraja dances in a ring of fire: his right hand holds the drum of creation, his left hand holds the flame of dissolution, one foot tramples the demon of ignorance, and the other is raised in liberation. The Thirumanthiram's description of Shiva's cosmic dance is one of its most celebrated passages.", category: "Deity", verseRefs: [338, 2] },
  { id: 101, tamil: "பைரவன்",                transliteration: "pairavaṉ",            english: "Bhairava — The Terrifying Form",              explanation: "Shiva in his fierce, awe-inspiring aspect — 'the terrifying.' Bhairava's fearsome appearance destroys attachment, ego, and the fear of death itself. In Shaiva tantra, Bhairava represents the transformative power that dissolves all boundaries between the devotee and Shiva. The Thirumanthiram's Tantra 4 includes teachings on Bhairava and Bhairavi as the dynamic pair of fierce liberation-energy.", category: "Deity", verseRefs: [885] },
  { id: 102, tamil: "அர்த்தநாரீசுவரர்",       transliteration: "arttanārīcuvarar",    english: "Ardhanarisvara — Half Shiva Half Shakti",     explanation: "The composite form of Shiva who is half male (Shiva) and half female (Parvati) — one of the most profound images in the tradition. This form declares that ultimate reality transcends gender: consciousness (Shiva) and energy (Shakti) are eternally inseparable. To see one without the other is to see only half of the truth.", category: "Deity", verseRefs: [2] },
  { id: 103, tamil: "அனுக்கிரகம்",            transliteration: "aṉukkirakam",         english: "Anugraha — Liberating Grace",                 explanation: "The fifth of Shiva's five cosmic acts — the grace that directly liberates the soul from the cycle of bondage and rebirth. While the first four acts are cosmic functions operating at a universal scale, anugraha is intensely personal: it is Shiva's individual blessing that lifts each specific soul toward liberation. The entire Thirumanthiram is an extended teaching on how anugraha works and how to receive it.", category: "Deity", verseRefs: [2, 338] },
  { id: 104, tamil: "ஐந்தொழில்",              transliteration: "aintoḻil",            english: "Aintozhil — Five Cosmic Acts of Shiva",       explanation: "Shiva's five inseparable cosmic functions that sustain the entire cycle of existence: Srishti (creation), Sthiti (preservation), Samhara (dissolution), Tirobhava (concealment), and Anugraha (liberation). These five acts are the complete account of how Shiva relates to the universe and to souls. Tantra 2 of the Thirumanthiram is devoted to expounding these five cosmic functions in detail.", category: "Cosmology", verseRefs: [338, 339] },
  { id: 105, tamil: "சேவடி",                  transliteration: "cēvaṭi",              english: "Red Feet of Shiva / Sacred Lotus Feet",        explanation: "The crimson lotus feet of Shiva — one of the most intimate objects of devotion in Tamil Shaiva poetry. While thiruvadi emphasises reverence, cēvaṭi carries the tone of intense personal love: the devotee's heart is like a bee that can only rest at the fragrant, beautiful red feet of the Lord. The Thirumanthiram uses this image repeatedly to express the depth of the devotee's surrender.", category: "Deity", verseRefs: [2, 80] },
  { id: 106, tamil: "சிவலிங்கம்",              transliteration: "civaliṅkam",          english: "Shiva Lingam — Supreme Symbol of Shiva",       explanation: "The complete symbol of Shiva — the upright column of pure consciousness (the lingam) arising from the circular base (the yoni, representing Shakti and the manifest world). The Shivalingam is simultaneously the most abstract and the most concrete image of Shiva: infinite, self-luminous consciousness grounded in and expressing through all of existence. Tantra 7 devotes many verses to the different forms of the Lingam.", category: "Deity", verseRefs: [1705, 885] },

  // ── Yoga — specific limbs, channels, chakras ────────────────────────────────
  { id: 107, tamil: "ஆசனம்",                  transliteration: "ācaṉam",              english: "Asana — Yogic Posture",                       explanation: "The third limb of Ashtanga yoga — postures that stabilise the body and purify its channels for meditation. In the Thirumanthiram, asana is not gymnastic exercise but the art of bringing the body into perfect stillness so that energy flows freely through the sushumna. A stable, effortless seat is the necessary foundation on which pranayama, dharana, and samadhi are built.", category: "Yoga", verseRefs: [550] },
  { id: 108, tamil: "பிராணாயாமம்",             transliteration: "pirāṇāyāmam",         english: "Pranayama — Breath Control",                   explanation: "The fourth limb of Ashtanga yoga — the disciplined regulation of breath to control and expand prana. The Thirumanthiram contains extensive teaching on pranayama as the master key of yoga: controlling breath controls mind, and controlling mind reveals Shiva. The three phases — inhalation (puraka), retention (kumbhaka), and exhalation (rechaka) — structure the complete practice.", category: "Yoga", verseRefs: [550, 551] },
  { id: 109, tamil: "நியமம்",                  transliteration: "niyamam",              english: "Niyama — Spiritual Observances",               explanation: "The second limb of Ashtanga yoga — the positive disciplines that cultivate the inner conditions for yoga: cleanliness (shaucha), contentment (santosha), austerity (tapas), self-study (svadhyaya), and surrender to God (Ishvara pranidhana). Where Yama defines what the yogi restrains, Niyama defines what is actively cultivated as daily spiritual discipline.", category: "Yoga", verseRefs: [550] },
  { id: 110, tamil: "தாரணை",                  transliteration: "tāraṇai",              english: "Dharana — Concentration",                     explanation: "The sixth limb of Ashtanga yoga — the sustained focusing of attention on a single object, centre, or point of consciousness. Dharana precedes dhyana: first the mind is gathered and directed, then sustained direction becomes natural absorption. In the Thirumanthiram, dharana is described as fixing the mind on Shiva until the boundary between meditator and object begins to dissolve.", category: "Yoga", verseRefs: [550] },
  { id: 111, tamil: "தியானம்",                 transliteration: "tiyāṉam",              english: "Dhyana — Meditation",                         explanation: "The seventh limb of Ashtanga yoga — the continuous, uninterrupted flow of attention toward the object of meditation. Dhyana deepens dharana: where dharana is effortful concentration, dhyana is effortless presence. Thirumoolar devotes extensive passages to the forms, objects, and fruits of dhyana, describing it as the portal through which the individual consciousness pours itself into Shiva-consciousness.", category: "Yoga", verseRefs: [550, 2123] },
  { id: 112, tamil: "முத்திரை",                transliteration: "muttirai",             english: "Mudra — Sacred Gesture / Seal",               explanation: "A sacred gesture, posture, or energy-seal that channels and directs the flow of prana in the body. Mudras can involve the hands, eyes, body, or breath. In Shaiva tantra, specific mudras are associated with particular deities, chakras, and states of consciousness — each one a physical encoding of a specific inner reality that, when correctly held, makes that reality accessible.", category: "Yoga", verseRefs: [885, 550] },
  { id: 113, tamil: "நாடி",                    transliteration: "nāṭi",                 english: "Nadi — Subtle Energy Channel",                explanation: "The subtle channels through which prana flows in the yogic body. Classical texts enumerate 72,000 nadis, of which three are paramount: Ida (left/lunar), Pingala (right/solar), and Sushumna (central). The Thirumanthiram describes the nadis as the inner rivers of the subtle body that must be purified and balanced so that Kundalini can rise safely through the central channel to the crown.", category: "Yoga", verseRefs: [550, 885] },
  { id: 114, tamil: "பிங்கலை",                 transliteration: "piṅkalai",             english: "Pingala — Right Solar Channel",               explanation: "The right energy channel (nadi) associated with the sun, heat, active energy, the masculine principle, and the out-breath. Pingala carries solar vital force along the right side. When Pingala is dominant, the mind is active, analytical, and extroverted. Balancing Pingala with the lunar Ida channel causes both to withdraw into the central Sushumna, opening it for Kundalini's ascent.", category: "Yoga", verseRefs: [550, 885] },
  { id: 115, tamil: "மூலாதாரம்",               transliteration: "mūlātāram",            english: "Muladhara — Root Chakra",                     explanation: "The first of the six chakras, located at the base of the spine — the foundation of the entire subtle body. Muladhara is the seat of dormant Kundalini energy, coiled three and a half times around the central channel. Its four-petalled lotus is associated with the earth element. All upward yogic progress begins with the awakening and purification of this root centre.", category: "Yoga", verseRefs: [550, 885] },
  { id: 116, tamil: "சுவாதிட்டானம்",           transliteration: "cuvāṭiṭṭāṉam",        english: "Svadhisthana — Sacral Chakra",                explanation: "The second chakra, located at the sacral region — the six-petalled lotus associated with the water element and the creative-emotional dimension of consciousness. Svadhishthana governs vital creative energy. Its purification allows the life-force to rise higher and be transmuted from personal creative energy into the impersonal creative power of Shiva.", category: "Yoga", verseRefs: [550] },
  { id: 117, tamil: "மணிபூரகம்",               transliteration: "maṇipūrakam",          english: "Manipura — Solar Plexus Chakra",              explanation: "The third chakra, located at the navel — the ten-petalled lotus associated with the fire element, personal will, and transformative energy. Manipura is the seat of digestive fire (agni) in both its physical and spiritual dimensions. Its awakening brings mastery over fire, radiant vitality, and the ability to transform experience — inwardly and outwardly.", category: "Yoga", verseRefs: [550] },
  { id: 118, tamil: "அநாகதம்",                 transliteration: "anākatam",             english: "Anahata — Heart Chakra",                      explanation: "The fourth chakra, located at the heart — the twelve-petalled lotus associated with the air element and the meeting point of personal and universal love. The name means 'unstruck': at this centre the inner sound (nāda) arises without being struck by anything external. Anahata is where the Kundalini energy first touches the domain of pure consciousness and love begins to transcend personal attachment.", category: "Yoga", verseRefs: [550, 885] },
  { id: 119, tamil: "விசுத்தி",                 transliteration: "vicutti",              english: "Vishuddha — Throat Chakra",                   explanation: "The fifth chakra, located at the throat — the sixteen-petalled lotus associated with the ether element and the purification of speech and sound. At Vishuddha, all speech becomes mantra, all sound becomes the divine vibration. The yogi who awakens this centre gains command over the subtler dimensions of nāda and the ability to transmit truth through every word.", category: "Yoga", verseRefs: [550, 885] },
  { id: 120, tamil: "ஆஞ்ஞை",                   transliteration: "āñcai",                english: "Ajna — Third Eye Chakra",                     explanation: "The sixth chakra, located between the eyebrows — the two-petalled lotus that is the seat of inner vision, intuition, and direct perception. At Ajna, the solar and lunar channels (Pingala and Ida) merge with the central Sushumna. Its awakening grants the yogi direct spiritual sight — the capacity to see through appearances to the Shiva-nature within all things.", category: "Yoga", verseRefs: [550, 885] },
  { id: 121, tamil: "சகஸ்ரதளம்",               transliteration: "cakasrataḷam",         english: "Sahasrara — Crown Chakra",                    explanation: "The thousand-petalled lotus at the crown of the head — the seventh and transcendent centre beyond the six chakras proper. Sahasrara is where Kundalini energy merges with Shiva at the summit of the subtle body, and individual consciousness dissolves into infinite consciousness. In the Thirumanthiram, this centre is described as the location of the supreme experience of Shiva — the final destination of all yoga.", category: "Yoga", verseRefs: [550, 2123] },

  // ── Philosophy — deeper concepts ─────────────────────────────────────────────
  { id: 122, tamil: "ஞானம்",                   transliteration: "ñāṉam",               english: "Jnana — Direct Knowing",                      explanation: "The path of direct knowledge — not intellectual theology but the living, experiential recognition of Shiva as one's own deepest nature. Jnana is the highest of the four Shaiva paths (Charya, Kriya, Yoga, Jnana). In the Thirumanthiram, Jnana is not separate from love or practice but is their ultimate fruition: the moment the soul recognises that it has always been what it was seeking.", category: "Philosophy", verseRefs: [1420, 2123] },
  { id: 123, tamil: "சரியை",                   transliteration: "cariyai",              english: "Charya — Right Conduct / Service",             explanation: "The first of the four Shaiva paths — the path of right conduct, ethical living, and selfless service in the world and in the temple. Charya is not an inferior path but the necessary foundation: without a life of integrity, compassion, and service, the higher paths of Kriya, Yoga, and Jnana have nothing to grow on. Thirumoolar teaches that every act of service is itself an act of worship.", category: "Practice", verseRefs: [1420] },
  { id: 124, tamil: "ஆனந்தம்",                 transliteration: "āṉantam",              english: "Ananda — Divine Bliss",                       explanation: "The intrinsic bliss of pure consciousness — not pleasure dependent on external conditions but the unconditional joy that is Shiva's own nature and the soul's deepest reality. Ananda is not attained but uncovered: as the soul's bonds dissolve through grace and practice, the ananda that was always present beneath them is simply recognised. It is the third component of the great triad Satchidananda.", category: "Philosophy", verseRefs: [2650, 2123] },
  { id: 125, tamil: "சச்சிதானந்தம்",           transliteration: "caccitāṉantam",        english: "Satchidananda — Being-Consciousness-Bliss",    explanation: "The three-fold description of ultimate reality: Sat (pure being), Chit (pure consciousness), Ananda (pure bliss). These are not three separate qualities but three aspects of the single, indivisible nature of Shiva. The liberated soul recognises its own nature as identical with this Satchidananda — it has always been being, consciousness, and bliss, merely obscured by the three bonds.", category: "Philosophy", verseRefs: [2123, 2650] },
  { id: 126, tamil: "சத்",                     transliteration: "cat",                  english: "Sat — Pure Being",                            explanation: "Pure, unconditioned existence — that which is eternally, unchangingly real. Shiva as Sat is the ground of all being, the existence in which everything else exists. Unlike individual things that arise and pass away, Sat never changes, never ceases, and had no beginning. Recognising Sat within one's own awareness is a central teaching of the Thirumanthiram.", category: "Philosophy", verseRefs: [2] },
  { id: 127, tamil: "சித்",                    transliteration: "cit",                  english: "Chit — Pure Consciousness",                   explanation: "Pure, self-luminous awareness — the knowing principle that illumines all experience without itself needing illumination. Shiva as Chit is the consciousness that makes all knowing possible. In the Thirumanthiram, recognising this pure consciousness as one's own deepest nature — identical with Shiva — is the essence of Jnana. Chit is what remains when all objects of experience are released.", category: "Philosophy", verseRefs: [2123] },
  { id: 128, tamil: "நித்தியம்",               transliteration: "nittiyam",             english: "Nitya — The Eternal",                         explanation: "That which is eternal, permanent, and unchanging. In the Thirumanthiram, only three realities are truly nitya: Shiva (Pati), the soul (Pasu), and the three bonds (Pasha). Everything else — all of the manifest world — is anitya (transient). Recognising the eternal within the impermanent is a core teaching: the body and the world will pass, but the soul and Shiva never cease.", category: "Philosophy", verseRefs: [114] },
  { id: 129, tamil: "அனித்தியம்",              transliteration: "anittiyam",            english: "Anitya — Impermanence",                       explanation: "The impermanent nature of all worldly things — body, youth, beauty, wealth, and fame. Tantra 1 of the Thirumanthiram opens with extended meditations on impermanence, not to induce despair but to redirect the soul's energy from transient appearances toward the eternal reality of Shiva. The clear recognition of impermanence is itself a form of grace.", category: "Philosophy", verseRefs: [114, 115] },
  { id: 130, tamil: "விவேகம்",                  transliteration: "vivēkam",              english: "Viveka — Spiritual Discernment",              explanation: "The capacity to discriminate between the real and the unreal, the eternal and the transient, the self and the not-self. Viveka is the faculty that makes all spiritual life possible: without it, the soul cannot recognise what is worth pursuing or what must be released. In Shaiva yoga, genuine viveka is not a human achievement but a gift of Shiva's grace that dawns when the soul turns inward.", category: "Philosophy", verseRefs: [114] },
  { id: 131, tamil: "வைராக்கியம்",             transliteration: "vairākkiyam",          english: "Vairagya — Dispassion",                       explanation: "The natural dispassion or non-attachment that arises when the soul genuinely recognises the impermanence of worldly things. Vairagya is not forced renunciation through gritted teeth but the natural cooling of desire in the light of clear seeing. In the Thirumanthiram, vairagya and viveka together create the inner freedom in which devotion, yoga, and jnana can grow without obstruction.", category: "Philosophy", verseRefs: [114, 1574] },
  { id: 132, tamil: "அத்துவிதம்",              transliteration: "attuaitam",            english: "Advaita — Non-Duality",                       explanation: "The philosophical position that ultimate reality is non-dual — there is only one absolute, and apparent multiplicity is not ultimately real. While Shaiva Siddhanta distinguishes itself from pure Advaita Vedanta by maintaining the eternal reality of souls and matter, it agrees that at the highest level of realisation the soul and Shiva are one — in experience if not in metaphysical substance.", category: "Philosophy", verseRefs: [2123] },
  { id: 133, tamil: "அஞ்ஞானம்",                transliteration: "añcñānam",             english: "Ajnana — Ignorance",                          explanation: "Spiritual ignorance — the fundamental not-knowing that causes the soul to mistake the transient for the real and the individual for the absolute. Ajnana is not mere intellectual error but a deep existential confusion rooted in the first bond, āṇava. Shiva's grace dissolves ajnana not by adding information but by removing the veil that was obscuring the ever-present light of Shiva-consciousness.", category: "Philosophy", verseRefs: [2123, 114] },
  { id: 134, tamil: "சாலோக்கியம்",             transliteration: "cālōkkiyam",           english: "Salokya — Dwelling in Shiva's Realm",          explanation: "The first of the four stages of liberation in Shaiva Siddhanta — dwelling in Shiva's realm (Sivaloka). The soul that attains Salokya abides in the same spiritual domain as Shiva, perceiving the divine presence continuously. It is an enormous leap from ordinary consciousness, yet is the beginning rather than the completion of the liberated life.", category: "Soul & Liberation", verseRefs: [2650] },
  { id: 135, tamil: "சாமீப்பியம்",             transliteration: "cāmīppiyam",           english: "Samipya — Nearness to Shiva",                  explanation: "The second stage of liberation — nearness and proximity to Shiva. The soul that attains Samipya dwells in Shiva's immediate presence, as close as a devoted servant to a beloved master. The distinction between soul and Shiva still remains, but the relationship has become one of constant, living proximity and intimacy.", category: "Soul & Liberation", verseRefs: [2650] },
  { id: 136, tamil: "சாரூப்பியம்",             transliteration: "cārūppiyam",           english: "Sarupya — Having Shiva's Form",                explanation: "The third stage of liberation — the soul takes on the radiant form of Shiva, sharing His attributes and appearance of pure light and bliss. In Sarupya, the soul is so saturated with Shiva's qualities that it shines with Shiva's own nature, though the distinction of souls still remains. This is sometimes described as 'becoming like God.'", category: "Soul & Liberation", verseRefs: [2650] },
  { id: 137, tamil: "சாயுச்சியம்",             transliteration: "cāyucciyam",           english: "Sayujya — Union with Shiva",                   explanation: "The fourth and highest stage of liberation — complete union with Shiva in which the soul abides permanently in Shiva-consciousness. In Sayujya, the soul's awareness becomes one with Shiva's awareness — not annihilated but fulfilled beyond measure. The Thirumanthiram's Tantra 9 is devoted to this supreme state, describing it as the soul's eternal home.", category: "Soul & Liberation", verseRefs: [2650, 2123] },

  // ── Practice — specific methods ───────────────────────────────────────────────
  { id: 138, tamil: "ஜபம்",                    transliteration: "japam",                english: "Japa — Mantra Repetition",                    explanation: "The practice of sustained, intentional repetition of a mantra. Japa can be vocal, whispered, or purely mental — the most subtle and most powerful form. The Thirumanthiram teaches that Japa of the Panchakshara (Namasivaya) gradually dissolves the three bonds and replaces the incessant chatter of the mind with the living presence of Shiva. Eventually, the mantra repeats itself — this is Ajapa, the highest form of japa.", category: "Practice", verseRefs: [885, 886] },
  { id: 139, tamil: "பூஜை",                    transliteration: "pūjai",                english: "Puja — Ritual Worship",                       explanation: "The formal ritual worship of Shiva through offerings of flowers, water, light, incense, food, and devotion. Each element of puja corresponds to an inner act: offering flowers is the offering of one's thoughts; offering light is the recognition of Shiva's light within. The Thirumanthiram teaches that external puja is the doorway to inner puja — the ultimate offering is the mind itself.", category: "Practice", verseRefs: [1705] },
  { id: 140, tamil: "திருநீறு",                transliteration: "tiruṉīṟu",             english: "Sacred Ash / Vibhuti",                        explanation: "The sacred white ash worn by Shaiva devotees on the forehead and body. Thiruneeru is produced by burning cow dung in a sacred fire and signifies the burning of karma through the fire of Shiva's grace, the impermanence of the body, and the purity of Shiva-consciousness. Tantra 6 devotes specific verses to the spiritual significance of wearing the sacred ash as an outward sign of inner transformation.", category: "Practice", verseRefs: [1574, 1575] },
  { id: 141, tamil: "ருத்திராட்சம்",            transliteration: "ruttrāṭcam",           english: "Rudraksha — Sacred Beads of Shiva",           explanation: "The berry of the Rudraksha tree, worn as sacred beads by Shaiva devotees and used in japa. The name means 'eye of Rudra (Shiva)' — according to the Thirumanthiram, Shiva's compassionate tears for suffering souls became the Rudraksha seeds. Wearing Rudraksha is believed to purify the aura, protect against negativity, and amplify the power of mantra repetition.", category: "Practice", verseRefs: [1574] },
  { id: 142, tamil: "அபிஷேகம்",                transliteration: "apiṣēkam",             english: "Abhishekam — Sacred Anointing",               explanation: "The ritual bathing of the Shiva Lingam or sacred image with water, milk, curd, honey, coconut water, and sandalwood paste. Each offering substance purifies a specific quality in the devotee who performs it. Abhishekam is one of the most beloved Shaiva rituals — through it the devotee participates directly in the care and adoration of the divine form.", category: "Practice", verseRefs: [1705] },
  { id: 143, tamil: "அஜபை",                    transliteration: "ajapaî",               english: "Ajapa — The Spontaneous Mantra",              explanation: "The mantra that breathes itself without any effort — the natural sound of the breath: 'So' on the inhalation and 'Ham' on the exhalation. Every living being spontaneously chants 'Soham' (I am That) 21,600 times per day without awareness of it. Tantra 4 of the Thirumanthiram contains significant teaching on Ajapa as the most intimate of all mantras — the recognition that the breath itself is Shiva's own voice within.", category: "Practice", verseRefs: [885, 886] },
  { id: 144, tamil: "உபதேசம்",                 transliteration: "upatēcam",             english: "Upadesa — Spiritual Instruction",             explanation: "Direct spiritual instruction transmitted from teacher to student — not mere information transfer but the living transmission of understanding that awakens recognition in the student's own consciousness. The entire Thirumanthiram is upadesa: Thirumoolar is giving direct teaching shaped from his own samādhi experience to awaken the same recognition in those who receive it with devotion and openness.", category: "Practice", verseRefs: [69, 2] },
  { id: 145, tamil: "வணக்கம்",                  transliteration: "vaṇakkam",             english: "Vanakkam — Reverence / Salutation",           explanation: "The gesture of deep reverence — both the external bow and the inner attitude of humility before the divine. Vaṇakkam is not mere social courtesy but a spiritual act: the bowing of the ego before the recognition of something infinitely greater. In the Thirumanthiram, all nine tantras can be understood as one continuous act of vaṇakkam — Thirumoolar placing his entire transmission at the feet of Shiva.", category: "Practice", verseRefs: [2] },
  { id: 146, tamil: "பரிகாரம்",                 transliteration: "parikāram",            english: "Parikara — Ritual Remedy / Grace Act",        explanation: "A remedial ritual or act of worship performed to address specific spiritual obstructions or karmic conditions. In the Thirumanthiram's practical teachings, certain practices serve as parikara — specific methods for dissolving specific types of karmic residue. Grace and parikara work together: the devotee performs the appropriate action; Shiva provides the liberating result.", category: "Practice" },

  // ── Scripture / Tradition ─────────────────────────────────────────────────────
  { id: 147, tamil: "திருமுறை",                transliteration: "tirumurai",             english: "Tirumurai — Sacred Canon of Shaivism",        explanation: "The twelve-volume canon of Tamil Shaiva devotional literature, compiled over many centuries from the hymns of the Nayanmars and other saints. The Thirumanthiram occupies the tenth position as a unique synthesis of devotion and direct yogic transmission. Together, the Tirumurais form the complete scriptural foundation of Tamil Shaivism and are regarded as equivalent in authority to the Sanskrit Vedas for Tamil devotees.", category: "Scripture", verseRefs: [2] },
  { id: 148, tamil: "தேவாரம்",                  transliteration: "tēvāram",               english: "Devaram — First Seven Tirumurai",              explanation: "The first seven volumes of the Tirumurai canon — the Tamil hymns of the three great Nayanmars: Thirugnanasambandar, Appar, and Sundarar. The Devaram establishes Tamil Shaivism's characteristic fusion of passionate personal love (bhakti) and rigorous theological precision. These hymns are sung in all Tamil Shaiva temples to this day.", category: "Scripture" },
  { id: 149, tamil: "திருவாசகம்",              transliteration: "tiruvācakam",           english: "Tiruvachakam — Sacred Utterances",             explanation: "The eighth Tirumurai, composed by Manikkavasagar — one of the most beloved devotional texts in Tamil. The title means 'sacred speech.' Manikkavasagar's verses overflow with the anguish and ecstasy of intense devotion. Tamil tradition says that 'the heart that does not melt at Tiruvachakam will not melt at anything.' The Thiruvachakam and Thirumanthiram together form the twin pillars of Tamil Shaiva mysticism.", category: "Scripture" },
  { id: 150, tamil: "சைவ சித்தாந்தம்",        transliteration: "caiva cittāntam",       english: "Shaiva Siddhanta — The Settled Doctrine",      explanation: "The systematic philosophical tradition of Tamil Shaivism — 'the settled, established truth of Shaivism.' Shaiva Siddhanta holds that Pati (God/Shiva), Pasu (souls), and Pasha (bonds) are three distinct eternal realities. It offers the most complete and internally consistent philosophical account of the Shaiva path, and the Thirumanthiram is its primary scriptural source and authority.", category: "Scripture", verseRefs: [2123, 2] },
  { id: 151, tamil: "நாயன்மார்கள்",            transliteration: "nāyaṉmārkaḷ",          english: "Nayanmars — The 63 Shaiva Saints",             explanation: "The 63 Tamil Shaiva saint-poets who composed the Devaram hymns, coming from all walks of life — kings, Brahmins, farmers, hunters, untouchables. The Nayanmars' lives embody the principle that sincere love for Shiva transcends all social boundaries. Their stories (recorded in the Periya Puranam) and their songs form the devotional foundation of Tamil Shaivism.", category: "Scripture" },
  { id: 152, tamil: "சிவஞானபோதம்",             transliteration: "civañānapōtam",        english: "Shivagnana Bodham — Revelation of Shiva-Knowledge", explanation: "The most celebrated philosophical text of Shaiva Siddhanta, composed by Meykandar (13th century) — twelve dense sutras expounding the relationship between Shiva, souls, and bonds. The Shivagnana Bodham systematises the teachings scattered throughout the Thirumanthiram into a compact philosophical treatise that became the foundational text of the Shaiva Siddhanta school.", category: "Scripture", verseRefs: [2123] },
  { id: 153, tamil: "உண்மை",                   transliteration: "uṇmai",                english: "Unmai — Truth / The Real",                    explanation: "Truth, reality, that which is real and genuine. In the Thirumanthiram, uṇmai points to the lived, experiential truth of Shiva — not doctrine believed on authority but the direct recognition of what is. Thirumoolar consistently distinguishes between conventional appearance (maya-generated) and uṇmai, the underlying reality that yoga and grace progressively reveal.", category: "Philosophy", verseRefs: [2, 2123] },

  // ── Cosmology / Sacred geography ─────────────────────────────────────────────
  { id: 154, tamil: "சிருட்டி",                 transliteration: "ciruṭṭi",              english: "Srishti — Cosmic Creation",                   explanation: "The first of Shiva's five cosmic acts — the continuous bringing-forth of the universe from the divine ground. Creation in the Thirumanthiram is not a one-time event but an ongoing, moment-by-moment arising: the entire universe is continuously being spoken into existence by Shiva. Creation is an act of divine compassion providing the arena for souls to mature through experience toward liberation.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 155, tamil: "திதி",                     transliteration: "titi",                  english: "Sthiti — Cosmic Preservation",                explanation: "The second of Shiva's five cosmic acts — the continuous sustaining and preservation of what has been created. Shiva as preserver maintains the ordered cosmos that allows souls to live, learn, and progress. In Shaiva cosmology, the preserving function is inseparable from grace: the cosmos is sustained specifically so that every soul has the time and space it needs to reach liberation.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 156, tamil: "சம்காரம்",                 transliteration: "camkāram",              english: "Samhara — Cosmic Dissolution",                explanation: "The third of Shiva's five cosmic acts — the reabsorption of the universe back into the divine ground at the end of each cosmic cycle. Samhara is not destruction but homecoming: like waves returning to the ocean, all manifestation dissolves back into Shiva. The Thirumanthiram presents this dissolution as an act of grace — releasing all accumulated karma so that the next cosmic cycle can begin fresh.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 157, tamil: "திருவம்பலம்",              transliteration: "tiruvampalam",          english: "Chidambaram — Sacred Hall of Consciousness",    explanation: "The sacred space at the centre of the universe where Shiva dances eternally as Nataraja — both the physical Chidambaram temple and the inner hall of pure awareness in the heart. 'Chit-ambaram' literally means 'space of consciousness.' The Thirumanthiram teaches that this divine hall is not located in Tamil Nadu but at the very centre of one's own being, ever-present and ever-accessible.", category: "Cosmology", verseRefs: [338, 885] },
  { id: 158, tamil: "கைலாயம்",                  transliteration: "kailāyam",              english: "Kailash — Shiva's Mountain Abode",             explanation: "The sacred mountain in the Himalayas that is Shiva's divine dwelling — simultaneously a physical place and a symbol of the highest spiritual reality. In the Thirumanthiram's biography, Thirumoolar descended from Kailash after years at Nandi's feet. Kailash represents the summit of attainment — the place where Shiva is directly known and where the lineage of Shaiva yoga originates.", category: "Cosmology", verseRefs: [80, 2] },
  { id: 159, tamil: "பஞ்சபூதம்",                transliteration: "pañcapūtam",            english: "Pancha Bhoota — The Five Elements",            explanation: "The five fundamental elements constituting the material universe: earth (maṇ), water (nīr), fire (neruppu), air (kāṟṟu), and space (ākāyam). In the Thirumanthiram's cosmology, these five are not merely physical substances but five modes of Shiva's own being. Correspondingly, the five chakras from Muladhara to Vishuddha are associated with these elements — making yoga the science of mastering the universe through mastering the body.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 160, tamil: "ஏழு உலகங்கள்",             transliteration: "ēḻu ulakaṅkaḷ",        english: "Seven Worlds / Realms of Existence",           explanation: "The seven levels of cosmic existence described in the Thirumanthiram: Bhuloka (earth), Bhuvarloka (atmosphere), Svarloka (heaven), Maharloka, Tapoloka, Satyaloka, and Sivaloka (Shiva's realm). These represent not merely spatial locations but progressive levels of consciousness — and correspond internally to the seven chakras of the yogic body from Muladhara to Sahasrara.", category: "Cosmology", verseRefs: [2] },
  { id: 161, tamil: "கர்ம வினை",                transliteration: "karma vinai",           english: "Karma Vinai — Action and Its Fruit",           explanation: "The law of action and its accumulated result across lifetimes — the second of the three bonds. Every intentional action creates a subtle imprint (samskara) that shapes future experience. The Thirumanthiram neither condemns the world nor collapses everything into fatalism: through devoted action, yoga, and grace, the accumulated vinai dissolves and the soul moves progressively toward freedom.", category: "Soul & Liberation", verseRefs: [114, 2123] },
  { id: 162, tamil: "சகல நிலை",                 transliteration: "cakala nilai",          english: "Sakala — Fully Bound State of the Soul",      explanation: "The first of three stages of the soul's journey in Shaiva Siddhanta. In Sakala, the soul is fully embedded in and identified with the material world, experiencing through body and mind under the influence of all three bonds. This is the ordinary human condition — not a fall from grace but a necessary stage in the soul's long education.", category: "Soul & Liberation" },
  { id: 163, tamil: "பிரளயாகலர்",               transliteration: "piralayākalar",        english: "Pralayakala — Souls Between Cosmic Cycles",    explanation: "The intermediate state of souls who have dissolved the maya bond but not yet the karma and āṇava bonds. Between cosmic cycles, these souls exist in a subtle state without the gross body, suspended until the next creation gives them the opportunity to continue their journey. The Thirumanthiram's cosmological teachings describe this and other soul-states in detail.", category: "Soul & Liberation" },
  { id: 164, tamil: "விஞ்ஞானகலர்",              transliteration: "viññānakalar",          english: "Vijnanakala — Souls Nearing Liberation",      explanation: "The most advanced state of bound souls — those who have dissolved both the maya and karma bonds and retain only the subtle āṇava bond. These souls are supremely pure and close to liberation but still held by the finest thread of primordial egoism. They require only the direct touch of Shiva's grace to break this final bond and enter into liberation.", category: "Soul & Liberation", verseRefs: [2123] },

  // ── Additional core terms ─────────────────────────────────────────────────────
  { id: 165, tamil: "இறை",                      transliteration: "iṟai",                 english: "Irai — The Divine / God",                     explanation: "The most intimate and universal Tamil word for God or the divine — 'that which pervades and governs.' Iṟai does not carry the weight of theological doctrine but points directly to the experienced, living divine presence that Thirumoolar refers to in everyday speech. It is the word a Tamil speaker reaches for when speaking of God without formality.", category: "Deity", verseRefs: [2] },
  { id: 166, tamil: "பேரின்பம்",                 transliteration: "pēriṉpam",              english: "Perinbam — Supreme Bliss",                    explanation: "The great, transcendent bliss that is Shiva's nature and the soul's deepest longing. Pēriṉpam is the Tamil expression for the supreme happiness that is not derived from any object or circumstance but wells up from the very ground of being. The Thirumanthiram describes this great bliss as the soul's natural state when freed from the three bonds.", category: "Philosophy", verseRefs: [2650, 276] },
  { id: 167, tamil: "தூய்மை",                   transliteration: "tūymai",               english: "Tuymai — Purity / Shuddha",                   explanation: "Purity — both outer and inner. In the Thirumanthiram, purity is not merely ritual cleanliness but the inner radiance that comes from the dissolution of the three bonds. The purified consciousness is like a clean mirror: it reflects Shiva perfectly, without the distortions of ego, desire, and karmic obscuration. All yogic practices are ultimately practices of progressive purification.", category: "Practice", verseRefs: [550] },
  { id: 168, tamil: "மோனம்",                    transliteration: "mōṉam",                english: "Monam — Sacred Silence",                      explanation: "The sacred inner silence that is the natural dwelling-state of the liberated yogi. Monam is not the absence of sound but the silence of the ego — the cessation of the mind's constant self-referential activity. In the Thirumanthiram, those who have 'attained the state of monam' (mōṉē nilai peṟṟār) are the truly realised ones who dwell in Shiva without needing words to describe it.", category: "Philosophy", verseRefs: [2123, 550] },
  { id: 169, tamil: "ஊழ்",                      transliteration: "ūḻ",                   english: "Uzh — Fate / Cosmic Law",                     explanation: "The immutable cosmic law or fate that arises from the accumulated karma of all beings. In the Thirumanthiram, ūḻ represents the bound, predetermined dimension of experience — the groove of past karma. But Shiva's grace is explicitly described as more powerful than ūḻ: divine grace can override karma, lifting the soul beyond its apparent destiny into liberation.", category: "Philosophy", verseRefs: [114] },
  { id: 170, tamil: "திருஞானசம்பந்தர்",         transliteration: "tiruñāṉacampantar",    english: "Thirugnanasambandar — Great Nayanmar Saint",   explanation: "One of the three great Nayanmars and the composer of the first, second, and third volumes of the Devaram. Thirugnanasambandar received Shiva's grace directly as a child through the divine milk of Parvati. His hymns burn with the urgency of a child's pure love. Though not part of the Thirumanthiram, understanding his role in Tamil Shaivism provides essential context for Thirumoolar's place in the tradition.", category: "Scripture" },
  { id: 171, tamil: "மாணிக்கவாசகர்",           transliteration: "māṇikkavācakar",        english: "Manikkavasagar — Saint of Tiruvachakam",       explanation: "One of the greatest saints of Tamil Shaivism and the author of the Tiruvachakam (eighth Tirumurai). His name means 'he whose speech is rubies.' Manikkavasagar's poems describe the anguish and bliss of a soul utterly consumed by love for Shiva. His combination of intellectual depth and emotional intensity makes him the closest in spirit among the Nayanmars to Thirumoolar.", category: "Scripture" },
  { id: 172, tamil: "சிவபெருமான்",              transliteration: "civapperumāṉ",          english: "Shivaperuman — The Great Lord Shiva",          explanation: "One of the most common full honorific names of Shiva in Tamil — 'the great, supreme Lord Shiva.' The addition of 'perum' (great) and 'mān' (lord) to 'Shiva' creates a name that conveys both immense greatness and personal intimacy. This is the name a Tamil devotee would use with the combination of reverence and familial love that characterises Tamil Shaivism at its deepest.", category: "Deity", verseRefs: [2] },
  { id: 173, tamil: "சாத்திரம்",                transliteration: "cātttiram",             english: "Shastra — Sacred Text / Science",             explanation: "A sacred text or systematised body of knowledge — the textual expression of a complete science of reality. The Thirumanthiram is itself described as a shastra — not a lyric poem alone but a complete shastra on yoga, cosmology, and liberation. In Tamil tradition, a shastra is the written form of what a guru would otherwise transmit orally in direct transmission.", category: "Scripture", verseRefs: [2] },
  { id: 174, tamil: "சிவபூஜை",                  transliteration: "civapūjai",             english: "Shiva Puja — Worship of Shiva",               explanation: "The complete ritual of Shiva worship including external offerings, internal meditation, and the devotional attitude that makes the ritual alive. The Thirumanthiram's Tantra 7 extensively describes different forms of Shiva Puja. The highest puja, Thirumoolar teaches, is the puja in which the devotee recognises that Shiva is both the one being worshipped and the one doing the worshipping.", category: "Practice", verseRefs: [1705, 1706] },
  { id: 175, tamil: "பேரொளி",                   transliteration: "pēroḷi",               english: "Peroli — The Great Light",                    explanation: "The vast, transcendent light of Shiva-consciousness — a light that has no external source, never dims, and pervades all of reality. In the Thirumanthiram, the inner experience of yoga culminates in the direct perception of this great light at the crown of the head. This light is Shiva Himself — not a vision of something external but the recognition of one's own fundamental nature as radiant awareness.", category: "Deity", verseRefs: [2123, 2] },
];

export function searchDictionary(query: string): DictionaryTerm[] {
  const q = query.toLowerCase().trim();
  if (!q) return DICTIONARY_TERMS;
  return DICTIONARY_TERMS.filter(
    (t) =>
      t.tamil.includes(q) ||
      t.transliteration.toLowerCase().includes(q) ||
      t.english.toLowerCase().includes(q) ||
      t.explanation.toLowerCase().includes(q),
  );
}
